using System.IO.Compression;
using System.Security.Cryptography;
using System.Text.Json;
using Aion.GameServer.Controllers.Attack.RetailNpc;
using Xunit;
using M = Aion.GameServer.Controllers.Attack.RetailNpc.RetailNpcEffectDurationStages;
using P = Aion.GameServer.Controllers.Attack.RetailNpc.RetailNpcSpellInstantParameters;
using S = Aion.GameServer.Controllers.Attack.RetailNpc.RetailNpcPeriodicSpellParameters;
namespace Aion.GameServer.Tests;
public class RetailNpcEffectDurationStagesTests
{
    private static readonly JsonElement Cases = Decode();
    public static IEnumerable<object[]> Arithmetic() => Enumerable.Range(0,Cases.GetProperty("arithmetic").GetArrayLength()).Select(i=>new object[]{i});
    public static IEnumerable<object[]> SourceBindings() => Enumerable.Range(0,Cases.GetProperty("selected").GetArrayLength()).Select(i=>new object[]{i});
    public static IEnumerable<object[]> DurationSlots() => Enumerable.Range(0,Cases.GetProperty("unify").GetArrayLength()).Select(i=>new object[]{i});
    [Theory,MemberData(nameof(Arithmetic))]
    public void CompleteFiniteDurationArithmeticMatchesExactRationalVectors(int index)
    {
        var row=Cases.GetProperty("arithmetic")[index];var a=row.GetProperty("args");
        float? multiplier=a[6].ValueKind==JsonValueKind.Null?null:BitConverter.UInt32BitsToSingle(a[6].GetUInt32());
        uint? percent=a[7].ValueKind==JsonValueKind.Null?null:a[7].GetUInt32();
        var r=M.CalculateBase(new(a[0].GetInt32(),(short)a[1].GetInt32(),a[2].GetInt32(),a[3].GetInt32(),a[4].GetInt32(),a[5].GetUInt32()),new(multiplier,percent));
        Check(row.GetProperty("expected"),r);
    }
    [Theory,MemberData(nameof(SourceBindings))]
    public void EverySelectedPeriodicBindingUsesItsOwnWholeSourceAndLevel(int index)
    {
        var row=Cases.GetProperty("selected")[index];var rec=row.GetProperty("record");var b=row.GetProperty("binding");
        int level=int.Parse(b.GetProperty("ordered_fields").EnumerateArray().Single(x=>x[0].GetString()=="skill_level")[1].GetString()!,System.Globalization.CultureInfo.InvariantCulture);
        var spell=P.ProjectSelectedSpell(Convert.FromBase64String(rec.GetProperty("raw").GetString()!),new(b.GetProperty("npc_id").GetInt32(),b.GetProperty("npc_devname").GetString()!,b.GetProperty("ordinal").GetInt32(),level,b.GetProperty("skill_name").GetString()!),P.RequiredPins);
        var r=M.CalculateSelectedPeriodic(S.Project(spell),0,new(1f,null));Check(row.GetProperty("expected"),r);
    }
    [Theory,MemberData(nameof(DurationSlots))]
    public void FirstNonzeroIncludingUnsignedSentinelGovernsLaterNonzeroSlots(int index)
    {
        var row=Cases.GetProperty("unify")[index];uint[] words=row.GetProperty("input").EnumerateArray().Select(x=>x.GetUInt32()).ToArray();
        var r=M.UnifyWithoutDeathPenalty(16594,words);
        Assert.Equal(row.GetProperty("first").GetUInt32(),r.FirstNonzero);
        Assert.Equal(row.GetProperty("expected").EnumerateArray().Select(x=>x.GetUInt32()),r.Durations);
        Assert.False(r.ActivationReady);Assert.False(r.HasDeathPenaltyAdjustment);
    }
    [Theory,InlineData(0x2058),InlineData(0x206b)] public void DeathPenaltyIsAnExplicitSeparateOwner(int id)=>Assert.Throws<ArgumentException>(()=>M.UnifyWithoutDeathPenalty(id,new uint[]{1000,5000}));
    [Fact] public void OversizedCompleteSlotDomainRejects()=>Assert.Throws<ArgumentException>(()=>M.UnifyWithoutDeathPenalty(16594,new uint[5]));
    [Fact] public void ExceptionalReachedFloatRejects()=>Assert.Throws<ArithmeticException>(()=>M.CalculateBase(new(0,23,200,8100,0,2000),new(float.NaN,null)));
    [Fact] public void UnrepresentableReachedCvttRejects()=>Assert.Throws<ArithmeticException>(()=>M.CalculateBase(new(0,1,0,int.MaxValue,0,0),new(1f,null)));
    [Fact] public void SentinelDoesNotReadExceptionalOrMissingModifiers()
    {
        var r=M.CalculateBase(new(1,23,200,8100,0,2000),new(float.NaN,uint.MaxValue));Assert.True(r.Infinite);Assert.Equal(uint.MaxValue,r.Value);
        Assert.Equal(r,M.CalculateBase(new(8,23,200,8100,0,2000),null!));
    }
    [Fact] public void PvpChildCannotAppearOutsideCallerBranch()=>Assert.Throws<ArgumentException>(()=>M.CalculateBase(new(0,23,200,8100,0,2000),new(null,100)));
    [Fact] public void MissingFormulaRejects()=>Assert.Throws<ArgumentNullException>(()=>M.CalculateBase(null!,new(null,null)));
    [Fact] public void MissingSelectedSourceRejects()=>Assert.Throws<ArgumentNullException>(()=>M.CalculateSelectedPeriodic(null!,0,new(null,null)));
    private static void Check(JsonElement e,M.Calculation r)
    {
        int? Int(int i)=>e[i].ValueKind==JsonValueKind.Null?null:e[i].GetInt32();
        uint? UInt(int i)=>e[i].ValueKind==JsonValueKind.Null?null:e[i].GetUInt32();
        uint? Bits(float? v)=>v.HasValue?BitConverter.SingleToUInt32Bits(v.Value):null;
        Assert.Equal(e[0].GetBoolean(),r.Infinite);Assert.Equal(Int(1),r.WrappedBase);
        Assert.Equal(UInt(2),Bits(r.CallerProduct));Assert.Equal(Int(3),r.AfterCaller);
        Assert.Equal(UInt(4),Bits(r.PvpRatio));Assert.Equal(UInt(5),Bits(r.PvpProduct));Assert.Equal(Int(6),r.AfterPvp);
        Assert.Equal(UInt(7),r.IntervalRemainder);Assert.Equal(e[8].GetUInt32(),r.Value);
        Assert.False(r.AppliesHpOrSchedules);Assert.False(r.CurrentOperandsProved);
    }
    private static JsonElement Decode()
    {
        using var src=new MemoryStream(Convert.FromBase64String(Blob));using var gzip=new GZipStream(src,CompressionMode.Decompress);using var dst=new MemoryStream();gzip.CopyTo(dst);
        byte[] raw=dst.ToArray();Assert.Equal("d9399b5adf7c7f26cf74226125090520558007510b6b2c586504ea40632ce22e",Convert.ToHexStringLower(SHA256.HashData(raw)));using var doc=JsonDocument.Parse(raw);return doc.RootElement.Clone();
    }
    private const string Blob="";
}
